import {ProgressBar} from '@primer/react'
import {DotFillIcon} from '@primer/octicons-react'
import {clsx} from 'clsx'
import styles from './LicenseCountCapped.module.css'

export interface Props {
  enterpriseLicensesConsumed: number
  enterpriseLicensesPurchased: number
  vssLicensesConsumed: number
  vssLicensesPurchased: number
}

export function LicenseCountCapped({
  enterpriseLicensesConsumed,
  enterpriseLicensesPurchased,
  vssLicensesConsumed,
  vssLicensesPurchased,
}: Props) {
  const totalAvailableLicenses = enterpriseLicensesPurchased + vssLicensesPurchased
  const totalConsumed = enterpriseLicensesConsumed + vssLicensesConsumed
  const enterpriseProgress =
    totalAvailableLicenses !== 0 ? (enterpriseLicensesConsumed / totalAvailableLicenses) * 100 : 100
  const vssProgress = totalAvailableLicenses !== 0 ? (vssLicensesConsumed / totalAvailableLicenses) * 100 : 100
  const showVss = vssLicensesPurchased > 0

  const ariaBreakdownTextEnterprise = `${enterpriseLicensesConsumed.toLocaleString()} Enterprise Cloud licenses.`
  const ariaBreakdownTextVss = showVss ? `${vssLicensesConsumed.toLocaleString()} Visual Studio licenses.` : ''

  return (
    <div className="mb-1 d-flex flex-column gap-2 width-full">
      <div className="d-flex flex-justify-between flex-items-baseline flex-wrap">
        <div className={clsx('f3', styles.lineHeightSpacious)} data-testid="license-count-total-consumed">
          {totalConsumed.toLocaleString()}
        </div>
        <div className="color-fg-muted no-wrap" data-testid="license-count-total-available">
          {totalAvailableLicenses.toLocaleString()} available
        </div>
      </div>
      <div>
        <ProgressBar
          barSize="small"
          aria-label="Consumed licenses"
          data-testid="license-count-progress-bar"
          aria-valuetext={`${ariaBreakdownTextEnterprise} ${ariaBreakdownTextVss}`}
        >
          <ProgressBar.Item
            key="enterprise"
            progress={enterpriseProgress}
            aria-label="Enterprise Cloud licenses"
            aria-valuetext={ariaBreakdownTextEnterprise}
            className={clsx(styles.enterpriseProgressBar)}
            data-testid="license-count-progress-enterprise"
            role="progressbar"
          />
          {showVss && (
            <ProgressBar.Item
              key="vss"
              progress={vssProgress}
              aria-label="Visual Studio licenses"
              aria-valuetext={ariaBreakdownTextVss}
              className={clsx(styles.vssProgressBar)}
              data-testid="license-count-progress-vss"
              role="progressbar"
            />
          )}
        </ProgressBar>
        {showVss && (
          <div className="d-flex flex-row mt-2 f6" data-testid="license-count-legend">
            <div className="d-flex flex-row flex-items-center mr-3">
              <DotFillIcon size={16} className="mr-1 fgColor-accent" />
              <span className="mr-1 text-bold">Enterprise Cloud</span>
              <span data-testid="license-count-legend-enterprise-count">
                {enterpriseLicensesConsumed.toLocaleString()}
              </span>
            </div>
            <div className="d-flex flex-row flex-items-center">
              <DotFillIcon size={16} className="mr-1 fgColor-success" />
              <span className="mr-1 text-bold">Visual Studio</span>
              <span data-testid="license-count-legend-vss-count">{vssLicensesConsumed.toLocaleString()}</span>
            </div>
          </div>
        )}
      </div>
    </div>
  )
}

try{ LicenseCountCapped.displayName ||= 'LicenseCountCapped' } catch {}