import {ProgressBar} from '@primer/react'

export interface LicenseCountProgressBarProps {
  consumedCount: number
  totalAvailableCount: number
  consumedBarClassName?: string
}

const DEFAULT_BAR_CLASS_NAME = 'bgColor-accent-emphasis'

export function LicenseCountProgressBar({
  consumedCount,
  totalAvailableCount,
  consumedBarClassName,
}: LicenseCountProgressBarProps) {
  const ariaLabelValue = `${consumedCount.toLocaleString()} licenses used.`
  const progress = totalAvailableCount !== 0 ? (consumedCount / totalAvailableCount) * 100 : 100
  return (
    <ProgressBar
      barSize="small"
      aria-label="Consumed licenses"
      data-testid="license-count-progress-bar"
      aria-valuetext={`${ariaLabelValue}`}
    >
      <ProgressBar.Item
        progress={progress}
        aria-label="Licenses used"
        aria-valuetext={ariaLabelValue}
        className={consumedBarClassName || DEFAULT_BAR_CLASS_NAME}
        data-testid="license-count-progress"
        role="progressbar"
      />
    </ProgressBar>
  )
}

try{ LicenseCountProgressBar.displayName ||= 'LicenseCountProgressBar' } catch {}